/* AIVIC_FUNCTION_BUNDLE_START owner=aggregateUnbilledAmountsForMonthlyClosing exports=aggregateUnbilledAmountsForMonthlyClosing */
const __aivicBundle_19_aggregateUnbilledAmountsForMonthlyClosing = (() => {
  function aggregateUnbilledAmountsForMonthlyClosing(
    deals: Array<{
      deal_id: string;
      customer_name: string;
      deal_amount: number;
      deal_status: string;
      invoice_issued_date: Date | null;
      deal_created_date: Date;
    }>,
    period_start: Date,
    period_end: Date
  ): UnbilledResult {
    const unbilled_deals: UnbilledDeal[] = [];
    let total_unbilled_amount = 0;
  
    for (const deal of deals) {
      const dealCreatedTime = deal.deal_created_date.getTime();
      const periodStartTime = period_start.getTime();
      const periodEndTime = period_end.getTime();
  
      const isWithinPeriod =
        dealCreatedTime >= periodStartTime && dealCreatedTime <= periodEndTime;
      const isUnbilled = deal.invoice_issued_date === null;
      const isContracted = deal.deal_status === "受注";
  
      if (isWithinPeriod && isUnbilled && isContracted) {
        unbilled_deals.push({
          deal_id: deal.deal_id,
          customer_name: deal.customer_name,
          unbilled_amount: deal.deal_amount,
        });
        total_unbilled_amount += deal.deal_amount;
      }
    }
  
    const periodStartStr = period_start.toISOString().split("T")[0];
    const periodEndStr = period_end.toISOString().split("T")[0];
    const periodStr = `${periodStartStr} to ${periodEndStr}`;
  
    return {
      total_unbilled_amount,
      unbilled_count: unbilled_deals.length,
      unbilled_deals,
      export_data: {
        period: periodStr,
        total_unbilled_amount,
        unbilled_count: unbilled_deals.length,
        details: unbilled_deals,
      },
    };
  }
  return { aggregateUnbilledAmountsForMonthlyClosing };
})();
