/* AIVIC_FUNCTION_BUNDLE_START owner=validateInvoiceAmount exports=validateInvoiceAmount */
const __aivicBundle_27_validateInvoiceAmount = (() => {
  function validateInvoiceAmount(input: {
    customerId: string;
    customerName: string;
    expectedAmount: number;
    actualAmount: number;
    tolerancePercentage: number;
  }): {
    isAnomalous: boolean;
    flagSet: boolean;
    notificationRequired: boolean;
    deviationAmount: number;
    deviationPercentage: number;
    notificationDetails?: {
      customerName: string;
      invoiceAmount: number;
      expectedAmount: number;
      deviationAmount: number;
      severity: string;
    };
  } {
    if (input["customerId"] === undefined || input["customerId"] === null) { throw new Error("customerId is required"); }
    const { customerName, expectedAmount, actualAmount, tolerancePercentage } = input;
  
    if (expectedAmount === 0) {
      throw new Error('期待金額は0より大きい値である必要があります');
    }
  
    if (tolerancePercentage < 0) {
      throw new Error('許容範囲は0以上である必要があります');
    }
  
    if (!customerName || customerName.trim() === '') {
      throw new Error('顧客名は空にできません');
    }
  
    const deviationAmount = actualAmount - expectedAmount;
    const deviationPercentage = (deviationAmount / expectedAmount) * 100;
  
    const absoluteDeviation = Math.abs(deviationPercentage);
    const isAnomalous = absoluteDeviation > tolerancePercentage;
  
    const result: {
      isAnomalous: boolean;
      flagSet: boolean;
      notificationRequired: boolean;
      deviationAmount: number;
      deviationPercentage: number;
      notificationDetails?: {
        customerName: string;
        invoiceAmount: number;
        expectedAmount: number;
        deviationAmount: number;
        severity: string;
      };
    } = {
      isAnomalous,
      flagSet: isAnomalous,
      notificationRequired: isAnomalous,
      deviationAmount,
      deviationPercentage,
    };
  
    if (isAnomalous) {
      let severity: string;
      if (absoluteDeviation > 20) {
        severity = 'HIGH';
      } else {
        severity = 'MEDIUM';
      }
  
      result.notificationDetails = {
        customerName,
        invoiceAmount: actualAmount,
        expectedAmount,
        deviationAmount,
        severity,
      };
    }
  
    return result;
  }
  return { validateInvoiceAmount };
})();
export const validateInvoiceAmount = __aivicBundle_27_validateInvoiceAmount.validateInvoiceAmount;
/* AIVIC_FUNCTION_BUNDLE_END owner=validateInvoiceAmount */

